//! What `tools/install.sh` lays on an account beyond the binary it places, and its undo,
//! as verbs of the installed binary (OF-38, INST-4):
//!
//! * `aterm pkg shell-setup` writes the managed PATH block in the shell profile, the
//!   shell completions (generated by this very binary, `<exe> --completions <shell>`), the
//!   man pages (a checkout's, or the ones this binary carries) and the Linux desktop entry
//!   with its icons (likewise).
//! * `aterm pkg self-uninstall` sweeps everything install.sh placed.
//!
//! install.sh keeps election, transport, verification, the swap, the toolchain step and
//! the source lane, and calls these once something runnable is placed;
//! `install.sh --uninstall` runs `self-uninstall`. Its location overrides
//! (`ATERM_INSTALL_DIR`, `ATERM_BIN_DIR`, `ATERM_STORE_DIR`, `ATERM_MAN_DIR`) arrive here
//! as flags.
//!
//! EVERY REMOVAL IS OWNERSHIP-CHECKED FIRST. The installer writes into shared, user-owned
//! locations (`/Applications`, `~/.local/bin`, the XDG man and completion trees) full of
//! things it did not put there, so "the path we would have written" is never reason
//! enough to delete. A bundle must identify as `com.aterm.aterm`; the `aterm` on PATH must
//! be a symlink into a bundle or the store; an entry of the store must be one the store
//! lanes place; a man page must be one aterm ships; a profile edit needs the exact marker
//! pair; a desktop entry needs its marker line. Anything else is SKIPPED with the reason,
//! never removed. A scoped run (`--install-dir`) removes only what the install in that
//! directory placed: while another aterm on the account remains, what is laid for the
//! whole account (the toolchain store, man pages, completions, the PATH block) is its too.

use std::borrow::Cow;
use std::ffi::{OsStr, OsString};
use std::io::Write;
use std::os::unix::fs::{MetadataExt as _, PermissionsExt as _};
use std::path::{Component, Path, PathBuf};
use std::process::ExitCode;
use std::time::{Duration, Instant};

/// The managed shell-profile block's marker PAIR: the writer and the sweep share it, and
/// only the exact pair authorises an edit of a profile.
pub const PATH_BLOCK_START: &str = "# >>> aterm ALab toolset (managed by install.sh) >>>";
/// The block's end marker.
pub const PATH_BLOCK_END: &str = "# <<< aterm ALab toolset <<<";
/// The first line of the Linux desktop entry `shell-setup --desktop` writes: the only thing
/// that authorises the sweep to remove `aterm.desktop` and the icons written with it
/// (`aterm` named an unrelated X11 terminal for decades). An on-disk contract across
/// versions — entries older installers wrote carry this exact line.
pub const DESKTOP_MARKER: &str =
    "# Managed by aterm install.sh — its uninstall removes only an entry carrying this line.";
