    [("1", "aterm.1", include_bytes!("../../../man/aterm.1"))];
/// An aterm bundle's identifier.
const BUNDLE_ID: &str = "com.aterm.aterm";
/// A hang detector on a child run to completion (this binary for its completions,
/// `update-desktop-database`, a binary this did not place for its `--version`, as
/// install.sh's `VERIFY_WAIT_SECS`), never a budget: a loaded machine only slows the
/// answer, and a child of these that never finishes is cut off.
const CHILD_HANG: Duration = Duration::from_secs(60);

/// Where install.sh lays things for this account: its defaults, or the overrides it was
/// run with.
#[derive(Clone, Debug)]
pub struct Places {
    /// `$HOME`.
    pub home: PathBuf,
    /// `$XDG_DATA_HOME`, else `~/.local/share`.
    pub xdg_data: PathBuf,
    /// `$XDG_CONFIG_HOME`, else `~/.config`.
    pub xdg_config: PathBuf,
    /// `ATERM_INSTALL_DIR`: THE app location of a scoped run; `None` scans `/Applications`
    /// and `~/Applications`.
    pub install_dir: Option<PathBuf>,
    /// `ATERM_BIN_DIR`, else `~/.local/bin`.
    pub bin_dir: PathBuf,
    /// `ATERM_STORE_DIR`, else `~/.local/lib/aterm/bin`.
    pub store_dir: PathBuf,
    /// `ATERM_MAN_DIR`, else `~/.local/share/man`.
    pub man_root: PathBuf,
}

impl Places {
    /// install.sh's defaults under `home`.
    #[must_use]
    pub fn defaults(home: &Path, xdg_data: Option<&Path>, xdg_config: Option<&Path>) -> Self {
        Self {
            home: home.to_path_buf(),
            xdg_data: xdg_data.map_or_else(|| home.join(".local/share"), Path::to_path_buf),
            xdg_config: xdg_config.map_or_else(|| home.join(".config"), Path::to_path_buf),
            install_dir: None,
            bin_dir: home.join(".local/bin"),
            store_dir: home.join(".local/lib/aterm/bin"),
            man_root: home.join(".local/share/man"),
        }
    }

    /// The bin dirs the sweep walks: the configured one, and `~/.local/bin` beside it when
    /// they differ — the app plants its own links there whatever `ATERM_BIN_DIR` says.
    fn bin_dirs(&self) -> Vec<PathBuf> {
        let local = self.home.join(".local/bin");
        let mut dirs = vec![self.bin_dir.clone()];
        if self.bin_dir != local {
            dirs.push(local);
        }
        dirs
    }

    /// The directories the app half installs `aterm.app` into: the scope alone, when set.
    fn app_dirs(&self) -> Vec<PathBuf> {
        self.install_dir.clone().map_or_else(
            || {
                vec![
                    PathBuf::from("/Applications"),
                    self.home.join("Applications"),
                ]
            },
            |dir| vec![dir],
        )
    }

    /// aterm's support directory, where atpkg keeps its store and its decline record.
    fn support(&self) -> PathBuf {
        self.home.join("Library/Application Support/aterm")
    }
}

/// What the shell side of the environment says: the login shell, `$PATH`, `$MANPATH`.
#[derive(Clone, Debug, Default)]
pub struct ShellEnv {
    /// The account's login shell, as the account record names it
    /// ([`crate::hooks::login_shell`]), never `$SHELL`, which a wrapper, a test or a parent
    /// process may set: the PATH block goes in the rc that shell reads ([`rc_target`]), the
    /// one file `base.shell.rc` creates too (docs/DESIGN-init-system-2026-10-20.md §4.2).
    pub shell: Option<String>,
    /// `$PATH`.
    pub path: Option<OsString>,
    /// `$MANPATH`.
    pub manpath: Option<String>,
}

impl ShellEnv {
    fn of_process() -> Self {
        Self {
            shell: crate::hooks::login_shell().map(|shell| shell.to_string_lossy().into_owned()),
            path: std::env::var_os("PATH"),
            manpath: std::env::var("MANPATH").ok(),
        }
    }

    /// The shell's name: the login shell's last component.
    fn shell_name(&self) -> &str {
        self.shell
            .as_deref()
            .map_or("", |s| s.rsplit('/').next().unwrap_or(s))
    }

    /// The first `name` on `$PATH` that is a file.
    fn on_path(&self, name: &str) -> Option<PathBuf> {
        let path = self.path.as_ref()?;
        std::env::split_paths(path)
            .map(|dir| dir.join(name))
            .find(|p| p.is_file())
    }
}

// ---------------------------------------------------------------------------------------
// shared predicates
// ---------------------------------------------------------------------------------------

/// The bundle's `CFBundleIdentifier`, read as `CFBundle` reads it, or `None`.
fn bundle_identifier(app: &Path) -> Option<String> {
    aterm_containment::consent::bundle_id_of(app, &[])
}

/// Whether `app` is an aterm bundle — the only kind either direction touches.
fn bundle_is_ours(app: &Path) -> bool {
    bundle_identifier(app).as_deref() == Some(BUNDLE_ID)
}

/// `path`'s symlink target, as written.
fn link_target(path: &Path) -> Option<String> {
    std::fs::read_link(path)
        .ok()
        .map(|t| t.to_string_lossy().into_owned())
}

/// Whether a bin entry is a symlink this installer places: into an aterm bundle, or into
/// the store.
fn bin_entry_is_ours(path: &Path, store: &Path) -> bool {
    link_target(path).is_some_and(|t| {
        t.contains("/aterm.app/Contents/MacOS/")
            || Path::new(&t).starts_with(store) && Path::new(&t) != store
    })
}

/// The aterm bundle the symlink `link` leads into, or `None`. A relative target is read
/// against the link's own directory, as the link resolves it.
fn link_bundle(link: &Path) -> Option<PathBuf> {
    let t = link_target(link)?;
    let t = if t.starts_with('/') {
        t
    } else {
        format!("{}/{t}", link.parent()?.display())
    };
    let at = t.find("/aterm.app/Contents/MacOS/")?;
    Some(PathBuf::from(format!("{}/aterm.app", &t[..at])))
}

/// Whether `a` and `b` are one file (device and inode).
fn same_file(a: &Path, b: &Path) -> bool {
    match (std::fs::metadata(a), std::fs::metadata(b)) {
        (Ok(x), Ok(y)) => x.dev() == y.dev() && x.ino() == y.ino(),
        _ => false,
    }
}

/// `path` as the deepest directory on it that exists, resolved, and the part below it
/// still to be created, without empty, `.` or `..` components — what `mkdir -p <path>`
/// would make. A `..` below a directory still to be created undoes that component, as
/// mkdir -p's walk does, and the result is split again (`new/../bin` IS `bin`).
fn dir_split(path: &Path) -> Option<(PathBuf, PathBuf)> {
    let mut path = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir().ok()?.join(path)
    };
    loop {
        let mut head = PathBuf::from("/");
        let mut comps = path.components().peekable();
        while let Some(c) = comps.peek() {
            let next = match c {
                Component::RootDir | Component::Prefix(_) => {
                    comps.next();
                    continue;
                }
                Component::CurDir => {
                    comps.next();
                    continue;
                }
                other => head.join(other.as_os_str()),
            };
            if !next.is_dir() {
                break;
            }
            head = next;
            comps.next();
        }
        let head = std::fs::canonicalize(&head).ok()?;
        let mut tail: Vec<OsString> = Vec::new();
        let mut undid = false;
        let mut base = head.clone();
        for c in comps {
            match c {
                Component::Normal(n) => tail.push(n.to_os_string()),
                Component::ParentDir => {
                    undid = true;
                    if tail.pop().is_none() {
                        base = base
                            .parent()
                            .map_or_else(|| base.clone(), Path::to_path_buf);
                    }
                }
                Component::CurDir | Component::RootDir | Component::Prefix(_) => {}
            }
        }
        if undid {
            path = tail.iter().fold(base, |p, t| p.join(t));
            continue;
        }
        return Some((head, tail.iter().collect()));
    }
}

/// Whether directory `a` lies within directory `b`, by identity: each physical ancestor of
/// `a` is compared with `b` by device and inode, so a symlinked spelling cannot hide that
/// two names are one directory. Where `b` does not exist yet, `a` lies in it only through
/// the same deepest existing directory and a spelling of the rest that starts with `b`'s.
fn dir_within(a: &Path, b: &Path) -> bool {
    let (Some((mut ah, at)), Some((bh, bt))) = (dir_split(a), dir_split(b)) else {
        return false;
    };
    if bt.as_os_str().is_empty() {
        loop {
            if same_file(&ah, &bh) {
                return true;
            }
            match ah.parent() {
                Some(p) => ah = p.to_path_buf(),
                None => return false,
            }
        }
    }
    same_file(&ah, &bh) && at.starts_with(&bt)
}

/// The first line `exe args…` prints within `within`, or nothing — stdin closed,
/// so a binary this did not place cannot swallow anything, nor hang the sweep.
fn first_line_bounded(exe: &Path, args: &[&str], within: Duration) -> String {
    let mut cmd = aterm_uds::spawnfd::command(exe);
    cmd.args(args);
    aterm_uds::deadline::output_until(&mut cmd, Instant::now() + within)
        .map(|out| {
            String::from_utf8_lossy(&out.stdout)
                .lines()
                .next()
                .unwrap_or_default()
                .to_string()
        })
        .unwrap_or_default()
}

/// Whether the regular executable file at `path` answers `--version` as aterm.
fn answers_as_aterm(path: &Path) -> bool {
    std::fs::symlink_metadata(path)
        .is_ok_and(|m| m.is_file() && m.permissions().mode() & 0o111 != 0)
        && first_line_bounded(path, &["--version"], CHILD_HANG).starts_with("aterm ")
}

/// Whether an entry of the store directory is one the store lanes place, judged by what it
/// is, not where it sits: the `aterm` binary (a regular file that answers `--version` as
/// aterm), an argv0 alias (a symlink to exactly `aterm`, whatever its name — it names the
/// binary beside it, and dangles once that goes), the Linux updater's private
/// `.aterm-update` directory, or a staging leftover of the store's atomic placement.
fn store_entry_is_ours(path: &Path) -> bool {
    let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
        return false;
    };
    let meta = std::fs::symlink_metadata(path);
    match name {
        "aterm" => answers_as_aterm(path),
        ".aterm-update" => meta.is_ok_and(|m| m.is_dir()),
        n if n.starts_with(".aterm-install.") => meta.is_ok_and(|m| m.is_file()),
        _ => link_target(path).as_deref() == Some("aterm"),
    }
}

/// Remove `path` as `rm -rf` does: a symlink itself, a directory with all it holds.
fn remove(path: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(path)?;
    if meta.is_dir() {
        std::fs::remove_dir_all(path)
    } else {
        std::fs::remove_file(path)
    }
}

/// Whether anything (a dangling symlink too) is at `path`.
fn present(path: &Path) -> bool {
    std::fs::symlink_metadata(path).is_ok()
}

// ---------------------------------------------------------------------------------------
// self-uninstall
// ---------------------------------------------------------------------------------------

/// The sweep's tally and its two channels.
struct Sweep<'w> {
    dry: bool,
    removed: usize,
    skipped: usize,
    kept: usize,
    shared_kept: usize,
    outsider: Option<PathBuf>,
    out: &'w mut dyn Write,
    err: &'w mut dyn Write,
}

impl Sweep<'_> {
    fn act(&self) -> &'static str {
        if self.dry { "would remove" } else { "remove" }
    }

    fn say(&mut self, line: &str) {
        let _ = writeln!(self.out, "atpkg: {line}");
    }

    /// Remove what is ours, or say what a real run would; an item that cannot be removed
    /// is SKIPPED and counted, and the sweep goes on.
    fn rm(&mut self, path: &Path, label: &str) {
        if self.dry {
            let act = self.act();
            self.say(&format!("{act} {label}: {}", path.display()));
        } else if remove(path).is_ok() {
            self.say(&format!("removed {label}: {}", path.display()));
        } else {
            let _ = writeln!(
                self.err,
                "atpkg: SKIPPED {label} (cannot remove, try sudo): {}",
                path.display()
            );
            self.skipped += 1;
            return;
        }
        self.removed += 1;
    }

    /// The one SKIPPED line for what is not ours.
    fn skip(&mut self, path: &str, reason: &str) {
        let _ = writeln!(self.err, "atpkg: SKIPPED {path} — {reason}");
        self.skipped += 1;
    }

    /// What is laid for the whole account: left while another aterm uses it.
    fn rm_shared(&mut self, path: &Path, label: &str) {
        if self.outsider.is_some() {
            self.say(&format!("left in place: {label}: {}", path.display()));
            self.kept += 1;
            self.shared_kept += 1;
        } else {
            self.rm(path, label);
        }
    }
}

/// Whether `bundle` is outside a scoped run's scope: anything but the entry `aterm.app` of
/// the install dir itself, judged by identity both ways. With no scope nothing is outside.
fn outside_scope(p: &Places, bundle: &Path) -> bool {
    let Some(scope) = &p.install_dir else {
        return false;
    };
    let entry = bundle.file_name().is_some_and(|n| n == "aterm.app")
        && bundle
            .parent()
            .is_some_and(|dir| dir_within(dir, scope) && dir_within(scope, dir));
    !entry
}

/// Whether `bundle` is another aterm than the scope's on this account: there, outside the
/// scope, and an aterm bundle.
fn other_aterm(p: &Places, bundle: &Path) -> bool {
    bundle.is_dir() && outside_scope(p, bundle) && bundle_is_ours(bundle)
}

/// The first aterm.app other than the scope's that runs on this HOME's toolchain store, or
/// `None`: the account's own app (`~/Applications`, and `/Applications` when HOME is the
/// account's home), and any app the account's commands lead into.
fn scope_outsider(p: &Places) -> Option<PathBuf> {
    let mut cands = vec![p.home.join("Applications/aterm.app")];
    if crate::platform::account_home().is_some_and(|acct| same_file(&acct, &p.home)) {
        cands.push(PathBuf::from("/Applications/aterm.app"));
    }
    for bd in p.bin_dirs() {
        for name in ["aterm", "atpkg"] {
            cands.extend(link_bundle(&bd.join(name)));
        }
    }
    cands.into_iter().find(|b| other_aterm(p, b))
}

/// The bundle whose helper step 0 may delegate to. Kept separate from running the
/// helper, so admission itself can be checked without any installation or uninstall.
fn uninstall_bundle(p: &Places) -> Option<PathBuf> {
    p.app_dirs()
        .iter()
        .map(|d| d.join("aterm.app"))
        .find(|app| {
            bundle_is_ours(app)
                && crate::toolchain::is_executable_file(&app.join("Contents/MacOS/atpkg"))
        })
}

/// Where the Caffeine mug keeps the copies of the app it runs from:
/// `<label>/<id>/X.app` (`<label>/X.app` before 2026-10-20), each copy's directory holding
/// [`aterm_uds::deadline::RAN`] once a mug ran from it ([`sweep_caffeine_code`]).
const CAFFEINE_CODE: &str = "caffeine-code.noindex";

/// What `aterm caffeine` keeps in the support dir: the copy of the app the mug runs from,
/// the session plists, the mode and the one-mug lock.
const CAFFEINE_FILES: [&str; 4] = [CAFFEINE_CODE, "caffeine", "caffeine.state", "caffeine.lock"];

/// The line a self-uninstall adds to the toolset decline its own sweep recorded but left for an
/// aterm it kept: the run that removes that aterm then knows the decline for the sweep's, not
/// the person's.
const SWEPT_DECLINE_TAG: &str = "# Recorded by aterm pkg self-uninstall for an aterm it kept.";

/// The prefix of every launchd label `aterm caffeine` makes, its login plists' names.
const CAFFEINE_LABEL_PREFIX: &str = "com.aterm.aterm.caffeine";

/// Retire the going builds' startup jobs and the running mug through their own command:
/// each going bundle's `aterm`, and the store's (the source lane's, which step 3 removes; a
/// bare build's mug runs from it where it is). With another aterm staying on the account,
/// only a going build's own mug is quit (`caffeine quit own`; a build from before it answers
/// a usage error, exit 2, and its mug is left as before). Shared files go only after every
/// admitted step succeeded and the mug lock is acquired for the whole cleanup. A refusal,
/// unsupported helper, or unknown/busy lock keeps them. The lock rendezvous itself stays:
/// unlinking a held lock would let another serve create a different inode while this cleanup
/// still holds the old one. Returns what holds each helper whose step failed (its bundle, or
/// the store's `aterm`): each is kept, as its `aterm caffeine` is what that step needs again.
fn sweep_caffeine(s: &mut Sweep<'_>, p: &Places, app_dirs: &[PathBuf]) -> Vec<PathBuf> {
    let support = p.support();
    let listed = || -> Vec<PathBuf> {
        CAFFEINE_FILES
            .iter()
            .map(|name| support.join(name))
            .filter(|path| present(path))
            .collect()
    };
    let files = listed();
    let login_plist = sorted_entries(&p.home.join("Library/LaunchAgents"))
        .iter()
        .filter_map(|plist| plist.file_name().and_then(|n| n.to_str()))
        .any(|name| name.starts_with(CAFFEINE_LABEL_PREFIX) && name.ends_with(".plist"));
    if files.is_empty() && !login_plist {
        return Vec::new();
    }
    let own_quit: &[&str] = &["caffeine", "quit", "own"];
    let steps: &[&[&str]] = if s.outsider.is_some() {
        &[&["caffeine", "startup", "off"], own_quit]
    } else {
        &[&["caffeine", "startup", "off"], &["caffeine", "quit"]]
    };
    let mut helpers: Vec<(PathBuf, PathBuf)> = app_dirs
        .iter()
        .map(|dir| dir.join("aterm.app"))
        .filter_map(|app| {
            let aterm = app.join("Contents/MacOS/aterm");
            (bundle_is_ours(&app) && crate::toolchain::is_executable_file(&aterm))
                .then_some((app, aterm))
        })
        .collect();
    let stored = p.store_dir.join("aterm");
    if store_left(p).is_none() && store_entry_is_ours(&stored) {
        helpers.push((stored.clone(), stored));
    }
    let mut supported = false;
    let mut failed = Vec::new();
    for (app, aterm) in helpers {
        if s.dry {
            s.say(&format!(
                "would ask {} help caffeine, then if supported:",
                aterm.display()
            ));
            for args in steps {
                s.say(&format!("would run {} {}", aterm.display(), args.join(" ")));
            }
            continue;
        }
        if run_quietly(&aterm, &["help", "caffeine"]) != 0 {
            continue;
        }
        supported = true;
        for args in steps {
            let line = format!("{} {}", aterm.display(), args.join(" "));
            match run_quietly(&aterm, args) {
                0 => s.say(&format!("ran {line}")),
                2 if *args == own_quit => s.say(&format!(
                    "{line}: this build cannot quit only its own mug; one it runs keeps running"
                )),
                rc => {
                    if !failed.contains(&app) {
                        failed.push(app.clone());
                    }
                    s.skip(
                        &line,
                        &format!(
                            "it failed (exit {rc}) — run it by hand to see why; {} is kept \
                             for it",
                            app.display()
                        ),
                    );
                }
            }
        }
    }
    if s.outsider.is_some() {
        for path in files {
            s.rm_shared(&path, "Caffeine file");
        }
        return failed;
    }
    if s.dry {
        s.say("Caffeine file removal requires an acquired idle lock; the lock itself stays");
        return failed;
    }
    // Listed again: `caffeine quit` removes the ended mug's copy itself, and an older build's
    // may have written a state file the first look did not see.
    let files = listed();
    if files.is_empty() {
        return failed;
    }
    if !supported || !failed.is_empty() {
        s.skip(
            &support.display().to_string(),
            "Caffeine stop was not confirmed; its files are kept",
        );
        return failed;
    }
    let lock = support.join("caffeine.lock");
    let Some(_hold) = caffeine_cleanup_hold(&lock) else {
        s.skip(
            &lock.display().to_string(),
            "Caffeine lock is busy or could not be acquired; its files are kept",
        );
        return failed;
    };
    // Listed once more, the lock with them: the hold makes it where no mug ever did.
    let files = listed();
    for path in files {
        if path == lock {
            s.say(&format!(
                "left Caffeine lock rendezvous: {}",
                path.display()
            ));
            s.kept += 1;
        } else if path == support.join(CAFFEINE_CODE) {
            sweep_caffeine_code(s, &path, std::time::SystemTime::now());
        } else {
            s.rm_shared(&path, "Caffeine file");
        }
    }
    failed
}

/// Remove the mug's code directory `code` at `now` as the mug's own sweep does: all of it but
/// a copy no mug said it ran from that is younger than the first-exec hang
/// ([`aterm_uds::deadline::copy_may_go`]). Its mug was stopped before it said so, so macOS may
/// still be assessing that copy's first exec, and on macOS 27.0.1 removing the file then
/// crashes `syspolicyd`, stranding every exec on the host. Such a copy, and the directories
/// holding it, stay, SKIPPED with when it may go: no aterm is left to remove it later.
fn sweep_caffeine_code(s: &mut Sweep<'_>, code: &Path, now: std::time::SystemTime) {
    let real_dir = |path: &Path| std::fs::symlink_metadata(path).is_ok_and(|m| m.is_dir());
    let partial = |path: &Path| path.extension().is_some_and(|e| e == "partial");
    let labels: Vec<PathBuf> = if real_dir(code) {
        sorted_entries(code)
    } else {
        Vec::new()
    };
    let young = |copy: &Path| {
        real_dir(copy) && !partial(copy) && !aterm_uds::deadline::copy_may_go(copy, now)
    };
    let holds_young = |label: &Path| {
        real_dir(label) && !partial(label) && sorted_entries(label).iter().any(|c| young(c))
    };
    if !labels.iter().any(|label| holds_young(label)) {
        s.rm_shared(code, "Caffeine file");
        return;
    }
    for label in labels {
        if !holds_young(&label) {
            s.rm(&label, "Caffeine file");
            continue;
        }
        for copy in sorted_entries(&label) {
            // The keep rule's own reading of what is left: time awake since the exec.
            let left = real_dir(&copy)
                .then(|| aterm_uds::deadline::copy_wait_left(&copy, now))
                .flatten()
                .filter(|_| !partial(&copy));
            let Some(left) = left else {
                s.rm(&copy, "Caffeine copy");
                continue;
            };
            s.skip(
                &copy.display().to_string(),
                &format!(
                    "no Caffeine mug said it ran from this copy, so macOS may still be assessing \
                     its first exec, and removing it now can crash syspolicyd; remove it by hand \
                     once the Mac has been awake {} more minute(s)",
                    left.as_secs().div_ceil(60).max(1)
                ),
            );
        }
    }
}

/// Hold the physical, owned regular rendezvous without waiting, made (`0600`) when no mug
/// ever made it: a `serve` starting meanwhile opens the same file and finds it held. An
/// error is unknown; a temporary probe would not preserve custody through the removals.
fn caffeine_cleanup_hold(path: &Path) -> Option<crate::lock::Flock> {
    use std::os::unix::fs::OpenOptionsExt as _;
    let file = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .mode(0o600)
        .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
        .open(path)
        .ok()?;
    let opened = file.metadata().ok()?;
    if !opened.is_file() || opened.uid() != aterm_uds::peer::our_uid() || opened.nlink() != 1 {
        return None;
    }
    let held = crate::lock::Flock::try_lock(file).ok()?;
    let named = std::fs::symlink_metadata(path).ok()?;
    if !named.is_file() || (named.dev(), named.ino()) != (opened.dev(), opened.ino()) {
        return None;
    }
    Some(held)
}

/// Run `program args`, its stdio `/dev/null`: its exit status, 127 when it could not run
/// and 128 when a signal ended it.
fn run_quietly(program: &Path, args: &[&str]) -> i32 {
    aterm_uds::spawnfd::command(program)
        .args(args)
        .stdin(aterm_uds::spawnfd::Stdio::null())
        .stdout(aterm_uds::spawnfd::Stdio::null())
        .stderr(aterm_uds::spawnfd::Stdio::null())
        .status()
        .map_or(127, |st| st.code().unwrap_or(128))
}

/// Everything install.sh placed, swept: the toolchain store (through the bundle's own
/// atpkg, before the bundle that carries it), the Caffeine mug (through the bundle's own
/// aterm, likewise), the app bundles, the decline that sweep recorded, the command links,
/// the source-built store, man pages, completions, the Linux desktop entry and icons, an
/// EMPTY support dir and the PATH block. `dry` says what a real run would do and changes
/// nothing; `man_src` is a checkout's `man/`, whose pages are aterm's too. `false` when
/// anything was SKIPPED.
pub fn self_uninstall(
    p: &Places,
    man_src: Option<&Path>,
    dry: bool,
    out: &mut dyn Write,
    err: &mut dyn Write,
) -> bool {
    let outsider = p.install_dir.as_ref().and_then(|_| scope_outsider(p));
    let mut s = Sweep {
        dry,
        removed: 0,
        skipped: 0,
        kept: 0,
        shared_kept: 0,
        outsider,
        out,
        err,
    };
    let support = p.support();
    let decline = support.join("pkg/declined");
    // A decline here before this run is the person's, unless a sweep tagged it as its own.
    let decline_tagged = std::fs::read_to_string(&decline)
        .is_ok_and(|text| text.lines().any(|line| line == SWEPT_DECLINE_TAG));
    let decline_before = present(&decline) && !decline_tagged;
    let app_dirs = p.app_dirs();

    // 0. THE TOOLCHAIN STORE, BEFORE THE BUNDLE THAT OWNS IT: the bundle's atpkg is the
    //    binary that knows how to remove the multi-GB store, and a scoped run reaches only
    //    the scope's bundle. A sweep that ran and failed keeps its bundle (its atpkg is the
    //    remedy — commonly a store lock the open app's pass holds, exit 75); an atpkg that
    //    could not run at all lets its bundle go.
    let atpkg_app = uninstall_bundle(p);
    let mut swept = false;
    let mut atpkg_kept: Option<PathBuf> = None;
    match (&atpkg_app, s.outsider.is_some()) {
        (Some(_), true) => {
            s.say("left in place: the ALab toolchain store");
            s.kept += 1;
            s.shared_kept += 1;
        }
        (Some(app), false) => {
            let atpkg = app.join("Contents/MacOS/atpkg");
            if dry {
                let act = s.act();
                s.say(&format!(
                    "{act} the ALab toolchain store: {} uninstall --all",
                    atpkg.display()
                ));
                s.removed += 1;
                swept = true;
            } else {
                let rc = aterm_uds::spawnfd::command(&atpkg)
                    .args(["uninstall", "--all"])
                    .stdin(aterm_uds::spawnfd::Stdio::null())
                    .stdout(aterm_uds::spawnfd::Stdio::null())
                    .stderr(aterm_uds::spawnfd::Stdio::null())
                    .status()
                    .map_or(127, |st| {
                        st.code().unwrap_or_else(|| {
                            128 + std::os::unix::process::ExitStatusExt::signal(&st).unwrap_or(0)
                        })
                    });
                if rc == 0 {
                    s.say("removed the ALab toolchain store");
                    swept = true;
                    s.removed += 1;
                } else if rc >= 126 {
                    s.skip(
                        "the ALab toolchain store",
                        &format!(
                            "`{} uninstall --all` could not run (exit {rc}) — reinstall aterm, \
                             then uninstall again",
                            atpkg.display()
                        ),
                    );
                } else {
                    let why = if rc == i32::from(crate::lock::CONTENDED_EXIT) {
                        "another aterm pkg run holds the store — quit aterm, or let its update \
                         pass finish"
                            .to_string()
                    } else {
                        format!("it failed (exit {rc}) — run it by hand to see why")
                    };
                    s.skip(
                        "the ALab toolchain store",
                        &format!(
                            "`{} uninstall --all`: {why}; {} is kept for it — then uninstall \
                             again",
                            atpkg.display(),
                            app.display()
                        ),
                    );
                    atpkg_kept = Some(app.clone());
                }
            }
        }
        (None, _) => {}
    }

    // 0b. THE CAFFEINE MUG, BEFORE THE BUNDLE IT RUNS FROM: see `sweep_caffeine`. A bundle
    //     whose step failed is kept: its `aterm caffeine` is the remedy.
    let caffeine_kept = sweep_caffeine(&mut s, p, &app_dirs);

    // 1. App bundles — every candidate dir (the scope alone, when set), aterm's only. The
    //    updater's apply leaves the outgoing bundle at `aterm.app.rollback`.
    for dir in &app_dirs {
        for name in ["aterm.app", "aterm.app.rollback"] {
            let app = dir.join(name);
            if !app.is_dir() {
                continue;
            }
            if atpkg_kept.as_ref() == Some(&app) {
                s.skip(
                    &app.display().to_string(),
                    "kept: its atpkg is what removes the ALab toolchain store, and that removal \
                     did not finish (above)",
                );
            } else if caffeine_kept.contains(&app) {
                s.skip(
                    &app.display().to_string(),
                    "kept: its `aterm caffeine` is what stops the Caffeine mug, and that did \
                     not finish (above)",
                );
            } else if bundle_is_ours(&app) {
                s.rm(&app, "app bundle");
            } else {
                let id = bundle_identifier(&app).unwrap_or_else(|| "unreadable".to_string());
                s.skip(
                    &app.display().to_string(),
                    &format!("not an aterm bundle (CFBundleIdentifier={id})"),
                );
            }
        }
    }

    // 1b. THE DECLINE THIS RUN'S SWEEP RECORDED: `uninstall --all` writes it for an aterm
    //     that stays; left once that aterm is gone, it would turn off the toolset half of
    //     every later install. A decline here before this run is the person's and stays. One
    //     an aterm kept above still needs is tagged, so the run that removes it removes the
    //     decline too.
    if (swept || decline_tagged) && !dry && !decline_before && decline.is_file() {
        let app_left = app_dirs.iter().any(|d| {
            let app = d.join("aterm.app");
            app.is_dir() && bundle_is_ours(&app)
        });
        if !app_left {
            let _ = std::fs::remove_file(&decline);
        } else if !decline_tagged {
            let tagged = std::fs::OpenOptions::new()
                .append(true)
                .open(&decline)
                .and_then(|mut file| writeln!(file, "{SWEPT_DECLINE_TAG}"));
            if let Err(e) = tagged {
                s.say(&format!(
                    "could not mark {} as this uninstall's: {e}",
                    decline.display()
                ));
            }
        }
    }

    // 2. The command links — `atpkg` and `aterm` — only when they lead into a bundle (or,
    //    for `aterm`, the store). A link into another aterm than the scope's is that
    //    aterm's; a real file is someone's own build.
    for bd in p.bin_dirs() {
        let atpkg_link = bd.join("atpkg");
        if let Some(t) = link_target(&atpkg_link) {
            if t.contains("/aterm.app/Contents/MacOS/") {
                rm_link(&mut s, p, &atpkg_link, "atpkg command");
            } else {
                s.skip(
                    &atpkg_link.display().to_string(),
                    "symlink points outside an aterm bundle",
                );
            }
        }
        let bin = bd.join("aterm");
        if bin_entry_is_ours(&bin, &p.store_dir) {
            rm_link(&mut s, p, &bin, "aterm command");
        } else if let Some(t) = link_target(&bin) {
            s.skip(
                &bin.display().to_string(),
                &format!("symlink points outside an aterm bundle or store ({t})"),
            );
        } else if present(&bin) {
            s.skip(
                &bin.display().to_string(),
                "not a symlink — a hand-built binary this installer did not place",
            );
        }
    }

    // 3. The store the source and Linux lanes fill: only what store_entry_is_ours
    //    recognises goes, and the directory with it only when it holds nothing else. An
    //    `aterm` whose Caffeine step failed stays, for that step.
    sweep_store(&mut s, p, &caffeine_kept);

    // 4. Man pages — only names aterm ships (or the checkout handed in ships): the glob is
    //    no authorisation, `aterm*` pages that are not ours exist in the wild.
    for section in 1..=9 {
        let dir = p.man_root.join(format!("man{section}"));
        for page in sorted_entries(&dir) {
            let Some(base) = page
                .file_name()
                .and_then(|n| n.to_str())
                .map(str::to_string)
            else {
                continue;
            };
            let man_page = base.starts_with("aterm")
                && base
                    .rsplit_once('.')
                    .is_some_and(|(_, ext)| matches!(ext.as_bytes(), [b'1'..=b'9']));
            if !man_page || !page.exists() {
                continue;
            }
            if SHIPPED_MAN_PAGES.contains(&base.as_str()) {
                s.rm_shared(&page, "man page");
            } else if !man_src.is_some_and(Path::is_dir) {
                s.skip(
                    &page.display().to_string(),
                    "not a man page this installer ships (run from a checkout to sweep newer \
                     pages)",
                );
            } else if !man_src.is_some_and(|src| src.join(&base).exists()) {
                s.skip(
                    &page.display().to_string(),
                    "not a man page this repo ships",
                );
            } else {
                s.rm_shared(&page, "man page");
            }
        }
    }

    // 5. Shell completions — the exact files `shell-setup --completions` writes.
    for comp in completion_files(p) {
        if comp.exists() {
            s.rm_shared(&comp, "shell completion");
        }
    }

    // 6. The Linux desktop identity: the marker line authorises the entry, and the entry
    //    found (or just removed) vouches for the icons written with it.
    let desktop = p.xdg_data.join("applications/aterm.desktop");
    let mut desktop_owned = false;
    let desktop_is_link =
        std::fs::symlink_metadata(&desktop).is_ok_and(|m| m.file_type().is_symlink());
    if desktop.is_file() || desktop_is_link {
        let owned = std::fs::symlink_metadata(&desktop).is_ok_and(|m| m.is_file())
            && std::fs::read_to_string(&desktop)
                .is_ok_and(|text| text.lines().any(|l| l == DESKTOP_MARKER));
        if owned {
            desktop_owned = true;
            s.rm(&desktop, "desktop entry");
            if !dry {
                refresh_desktop_database(&ShellEnv::of_process(), &p.xdg_data);
            }
        } else {
            s.skip(
                &desktop.display().to_string(),
                "not a desktop entry this installer wrote (missing its marker line)",
            );
        }
    }
    for size in ICON_SIZES {
        let icon = p
            .xdg_data
            .join(format!("icons/hicolor/{size}/apps/aterm.png"));
        if !icon.exists() {
            continue;
        }
        if desktop_owned {
            s.rm(&icon, "app icon");
        } else {
            s.skip(
                &icon.display().to_string(),
                "no marker-owned aterm.desktop vouches for it",
            );
        }
    }

    // 7. The support dir when EMPTY: rmdir, never more; a dry run probes it.
    if support.is_dir() {
        if dry {
            if std::fs::read_dir(&support).is_ok_and(|mut rd| rd.next().is_none()) {
                let act = s.act();
                s.say(&format!("{act} empty support dir: {}", support.display()));
                s.removed += 1;
            }
        } else if std::fs::remove_dir(&support).is_ok() {
            s.say(&format!("removed empty support dir: {}", support.display()));
            s.removed += 1;
        }
    }

    // 8. The PATH block, only between the exact marker pair, rewritten through the
    //    profile's own inode so it keeps its permissions.
    sweep_path_blocks(&mut s, p);

    if let Some(other) = s.outsider.clone()
        && s.shared_kept > 0
    {
        let n = s.shared_kept;
        s.say(&format!(
            "left in place: {n} account-wide item(s) above — {}, another aterm on this \
             account, uses them",
            other.display()
        ));
    }
    if s.removed == 0 && s.skipped == 0 && s.kept == 0 {
        s.say("nothing installed by install.sh was found — nothing to do");
        return true;
    }
    let verb = if dry { "dry run" } else { "uninstall" };
    let tail = if s.skipped > 0 {
        format!(", {} skipped", s.skipped)
    } else {
        String::new()
    };
    let removed = s.removed;
    s.say(&format!("{verb} complete — {removed} item(s){tail}"));
    let settings = p.xdg_config.join("aterm");
    if swept || (atpkg_app.is_some() && s.outsider.is_some()) {
        s.say(&format!(
            "left in place: your settings and themes in {}",
            settings.display()
        ));
    } else {
        s.say(&format!(
            "left in place: your settings and themes in {}, and any atpkg toolchain",
            settings.display()
        ));
    }
    if decline.is_file() {
        s.say(&format!(
            "left in place: the ALab toolset decline ({}) — installing aterm again installs \
             no toolset until `aterm pkg install --default-set`",
            decline.display()
        ));
    }
    s.skipped == 0
}

/// Remove a command link — unless it leads into another aterm than the scope's, whose
/// link it is.
fn rm_link(s: &mut Sweep<'_>, p: &Places, link: &Path, label: &str) {
    match link_bundle(link) {
        Some(b) if other_aterm(p, &b) => {
            s.say(&format!(
                "left in place: {} — it leads into {}, another aterm than ATERM_INSTALL_DIR's",
                link.display(),
                b.display()
            ));
            s.kept += 1;
        }
        _ => s.rm(link, label),
    }
}

/// The entries of `dir`, sorted, the dot-named ones after the rest (a shell glob's order);
/// none when it cannot be read.
fn sorted_entries(dir: &Path) -> Vec<PathBuf> {
    let Ok(rd) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut names: Vec<OsString> = rd.flatten().map(|e| e.file_name()).collect();
    names.sort_by_key(|n| (n.to_string_lossy().starts_with('.'), n.clone()));
    names.into_iter().map(|n| dir.join(n)).collect()
}

/// Why step 3 leaves the store as it is, when it does ([`sweep_store`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StoreLeft {
    /// No directory is there.
    Absent,
    /// It is a PATH directory, not a store of its own.
    PathDir,
    /// It cannot be listed.
    Unlisted,
}

/// Whether step 3 leaves the store as it is ([`StoreLeft`]); `None` when it sweeps it.
fn store_left(p: &Places) -> Option<StoreLeft> {
    let store = &p.store_dir;
    if !store.is_dir() {
        Some(StoreLeft::Absent)
    } else if p.bin_dirs().iter().any(|bd| same_file(store, bd)) {
        Some(StoreLeft::PathDir)
    } else if std::fs::read_dir(store).is_err() {
        Some(StoreLeft::Unlisted)
    } else {
        None
    }
}

/// Step 3 of [`self_uninstall`]; an entry in `caffeine_kept` is kept ([`sweep_caffeine`]).
fn sweep_store(s: &mut Sweep<'_>, p: &Places, caffeine_kept: &[PathBuf]) {
    let store = &p.store_dir;
    match store_left(p) {
        None => {}
        Some(StoreLeft::Absent) => return,
        Some(StoreLeft::PathDir) => {
            s.skip(
                &store.display().to_string(),
                "it is the PATH directory itself, not a store of its own — nothing in it was \
                 removed as the store's (ATERM_STORE_DIR needs a directory of its own)",
            );
            return;
        }
        Some(StoreLeft::Unlisted) => {
            s.skip(
                &store.display().to_string(),
                "cannot be listed, so what it holds cannot be judged — left in place",
            );
            return;
        }
    }
    let (own, foreign): (Vec<PathBuf>, Vec<PathBuf>) = sorted_entries(store)
        .into_iter()
        .partition(|entry| store_entry_is_ours(entry));
    let (kept, own): (Vec<PathBuf>, Vec<PathBuf>) = own
        .into_iter()
        .partition(|entry| caffeine_kept.contains(entry));
    let is_link = std::fs::symlink_metadata(store).is_ok_and(|m| m.file_type().is_symlink());
    if foreign.is_empty() && kept.is_empty() && !is_link {
        s.rm(store, "source-built toolset");
        return;
    }
    for entry in &kept {
        s.skip(
            &entry.display().to_string(),
            "kept: its `aterm caffeine` is what stops the Caffeine mug, and that did not \
             finish (above)",
        );
    }
    // A symlinked store is the person's link: what it leads to that is ours goes.
    for entry in &own {
        s.rm(entry, "source-built toolset entry");
    }
    if !foreign.is_empty() {
        let mut shown = foreign
            .iter()
            .take(3)
            .filter_map(|e| e.file_name().map(|n| n.to_string_lossy().into_owned()))
            .collect::<Vec<_>>()
            .join(", ");
        if foreign.len() > 3 {
            shown.push_str(&format!(" and {} more", foreign.len() - 3));
        }
        s.skip(
            &store.display().to_string(),
            &format!(
                "holds files this installer did not place ({shown}) — left in place with them"
            ),
        );
    }
}

/// Step 8 of [`self_uninstall`]: every profile either writer has ever targeted, each once.
fn sweep_path_blocks(s: &mut Sweep<'_>, p: &Places) {
    let mut rcs: Vec<PathBuf> = Vec::new();
    for rc in [
        p.home.join(".zshrc"),
        p.home.join(".bashrc"),
        p.home.join(".bash_profile"),
        p.home.join(".bash_login"),
        p.home.join(".profile"),
        p.xdg_config.join("fish/config.fish"),
        p.home.join(".config/fish/config.fish"),
    ] {
        if !rcs.contains(&rc) {
            rcs.push(rc);
        }
    }
    for rc in rcs {
        if !rc.is_file() {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(&rc) else {
            continue;
        };
        if !text.contains(PATH_BLOCK_START) {
            continue;
        }
        if s.outsider.is_some() {
            s.rm_shared(&rc, "PATH block");
            continue;
        }
        // The documented authorisation is the exact PAIR: a lone start marker means the
        // block was edited, and dropping to end-of-file would take the rest of the profile.
        if !text.contains(PATH_BLOCK_END) {
            s.skip(
                &rc.display().to_string(),
                "start marker without its end marker — delete the aterm block by hand",
            );
            continue;
        }
        if s.dry {
            let act = s.act();
            s.say(&format!("{act} PATH block: {}", rc.display()));
            s.removed += 1;
            continue;
        }
        match without_block(&text) {
            Some(kept)
                if std::fs::OpenOptions::new()
                    .write(true)
                    .truncate(true)
                    .open(&rc)
                    .and_then(|mut f| f.write_all(kept.as_bytes()))
                    .is_ok() =>
            {
                s.say(&format!("removed PATH block: {}", rc.display()));
                s.removed += 1;
            }
            _ => s.skip(
                &rc.display().to_string(),
                "could not rewrite the profile — delete the aterm block by hand",
            ),
        }
    }
}

/// `text` without the lines from an exact [`PATH_BLOCK_START`] line to the next exact
/// [`PATH_BLOCK_END`] line, both included; `None` when a block never ends.
fn without_block(text: &str) -> Option<String> {
    let mut out = String::with_capacity(text.len());
    let mut dropping = false;
    for line in text.split_inclusive('\n') {
        let bare = line.strip_suffix('\n').unwrap_or(line);
        if bare == PATH_BLOCK_START {
            dropping = true;
        } else if bare == PATH_BLOCK_END {
            dropping = false;
        } else if !dropping {
            out.push_str(line);
        }
    }
    (!dropping).then_some(out)
}

// ---------------------------------------------------------------------------------------
// shell-setup
// ---------------------------------------------------------------------------------------

/// The profile the managed PATH block lands in for `env`'s shell — the ONE election the
/// plan and the write share, and the one a pass's login rc comes from
/// ([`crate::hooks::login_rc`], fed the account record's shell) — or `None` for a shell
/// this does not know, which is told, never guessed at (a wrong line in a login file is
/// worse than none).
pub(crate) fn rc_target(p: &Places, env: &ShellEnv) -> Option<PathBuf> {
    match env.shell_name() {
        "zsh" => Some(p.home.join(".zshrc")),
        // macOS terminals spawn LOGIN shells, and login bash reads ~/.bash_profile (then
        // .bash_login, then .profile), never .bashrc: the first it will read, else
        // .bash_profile. On Linux, interactive terminals are non-login: .bashrc.
        "bash" if cfg!(target_os = "macos") => Some(
            [".bash_profile", ".bash_login", ".profile"]
                .iter()
                .map(|f| p.home.join(f))
                .find(|f| f.is_file())
                .unwrap_or_else(|| p.home.join(".bash_profile")),
        ),
        "bash" => Some(p.home.join(".bashrc")),
        // fish resolves its config through XDG_CONFIG_HOME.
        "fish" => Some(p.xdg_config.join("fish/config.fish")),
        _ => None,
    }
}

/// The toolset hook for `shell`, which atpkg writes ([`crate::hooks::HOOK_BASENAME`]).
fn hook_of(p: &Places, shell: &str) -> PathBuf {
    p.home.join(format!(
        ".aterm/shell.d/{}.{shell}",
        crate::hooks::HOOK_BASENAME
    ))
}

/// What `shell-setup` is asked to do.
#[derive(Clone, Debug, Default)]
pub struct Setup {
    /// Wire the managed PATH block.
    pub path: bool,
    /// Write the shell completions.
    pub completions: bool,
    /// Install the man pages of this directory (a checkout's `man/`).
    pub man: Option<PathBuf>,
    /// Install the man pages this binary carries (a piped install has no checkout's
    /// `man/`); [`Setup::man`] wins when both are asked.
    pub own_man: bool,
    /// Write the Linux desktop entry for `<bin dir>/aterm`.
    pub desktop: bool,
    /// The hicolor icon tree to install beside the desktop entry (a checkout's
    /// `assets/linux/icons/hicolor`); without one, the icons this binary carries.
    pub icons: Option<PathBuf>,
    /// The toolset hook is coming (a first launch lays it): write the block before it is
    /// there, as the line it carries guards on the hook's existence.
    pub toolset_coming: bool,
    /// Say what would be done, and do nothing.
    pub dry_run: bool,
}

/// `aterm pkg shell-setup`: the PATH block, completions, man pages and the desktop entry,
/// as asked. `exe` is
/// the binary whose `--completions` are written. `false` when a PATH block was asked for
/// and none stands when this returns.
pub fn shell_setup(
    p: &Places,
    env: &ShellEnv,
    exe: &Path,
    setup: &Setup,
    out: &mut dyn Write,
    err: &mut dyn Write,
) -> bool {
    let mut ok = true;
    if setup.path {
        ok = if setup.dry_run {
            plan_path(p, env, setup.toolset_coming, out);
            true
        } else {
            wire_path(p, env, setup.toolset_coming, out, err)
        };
    }
    if let Some(src) = &setup.man {
        let from = src.display().to_string();
        install_man_pages(p, env, &checkout_pages(src), &from, setup.dry_run, out, err);
    } else if setup.own_man {
        install_man_pages(
            p,
            env,
            &carried_pages(),
            "this binary",
            setup.dry_run,
            out,
            err,
        );
    }
    if setup.completions {
        install_completions(p, env, exe, setup.dry_run, out, err);
    }
    if setup.desktop {
        install_desktop_entry(p, env, setup.icons.as_deref(), setup.dry_run, out, err);
    }
    ok
}

/// The PATH line of a plan: what [`wire_path`] would do, decided the same way.
fn plan_path(p: &Places, env: &ShellEnv, coming: bool, out: &mut dyn Write) {
    let line = match rc_target(p, env) {
        None => format!(
            "PATH: unrecognised shell ({}) — no profile is edited; a source hint prints \
             instead",
            env.shell.as_deref().unwrap_or("<unset>")
        ),
        Some(rc) if std::fs::read_to_string(&rc).is_ok_and(|t| t.contains(&path_block(p, env))) => {
            format!(
                "PATH: already wired — {} carries the managed block; no edit",
                rc.display()
            )
        }
        Some(_) if !(coming || hook_of(p, env.shell_name()).is_file()) => {
            "PATH: no edit — no ALab toolset to put on PATH".to_string()
        }
        Some(rc) => {
            let verb = if std::fs::read_to_string(&rc).is_ok_and(|t| t.contains(PATH_BLOCK_START)) {
                "updates the"
            } else {
                "appends ONE"
            };
            format!(
                "PATH: {verb} marker-fenced block to {} — the toolset hook + {}",
                rc.display(),
                p.bin_dir.display()
            )
        }
    };
    let _ = writeln!(out, "atpkg: {line}");
}

/// The CLI link directory leads an inherited bundle. Source the package hook AFTER
/// that move so reroute/agents retain first priority and the managed package bin stays
/// appended. The runtime move also fixes a directory already present later on PATH.
fn path_block(p: &Places, env: &ShellEnv) -> String {
    let hook = hook_of(p, env.shell_name());
    let body = if env.shell_name() == "fish" {
        let bin = crate::hooks::fish_quote(&p.bin_dir);
        let hook = crate::hooks::fish_quote(&hook);
        format!(
            "set -l __aterm_cli_bin \"{bin}\"\n\
             set -l __aterm_cli_rest\n\
             for __aterm_cli_entry in $PATH; if test \"$__aterm_cli_entry\" != \"$__aterm_cli_bin\"; set __aterm_cli_rest $__aterm_cli_rest \"$__aterm_cli_entry\"; end; end\n\
             set -gx PATH \"$__aterm_cli_bin\" $__aterm_cli_rest\n\
             if test -f \"{hook}\"; source \"{hook}\"; end\n"
        )
    } else {
        let bin = crate::hooks::sh_quote(&p.bin_dir);
        let hook = crate::hooks::sh_quote(&hook);
        format!(
            "__aterm_cli_bin=\"{bin}\"\n\
             __aterm_cli_path=\":$PATH:\"\n\
             while :; do __aterm_cli_next=\"${{__aterm_cli_path//\":$__aterm_cli_bin:\"/:}}\"; [ \"$__aterm_cli_next\" = \"$__aterm_cli_path\" ] && break; __aterm_cli_path=\"$__aterm_cli_next\"; done\n\
             case \"$__aterm_cli_path\" in :) export PATH=\"$__aterm_cli_bin\" ;; *) __aterm_cli_path=\"${{__aterm_cli_path#:}}\"; __aterm_cli_path=\"${{__aterm_cli_path%:}}\"; export PATH=\"$__aterm_cli_bin:$__aterm_cli_path\" ;; esac\n\
             unset __aterm_cli_bin __aterm_cli_path __aterm_cli_next\n\
             if [ -f \"{hook}\" ]; then . \"{hook}\"; fi\n"
        )
    };
    format!("{PATH_BLOCK_START}\n{body}{PATH_BLOCK_END}\n")
}

/// Replace only the exact managed section, preserving every byte around it.
fn profile_with_path_block(text: &str, block: &str) -> Result<String, &'static str> {
    let (mut start, mut end, mut offset) = (None, None, 0);
    for line in text.split_inclusive('\n') {
        match line.trim_end_matches(['\r', '\n']) {
            PATH_BLOCK_START if start.is_none() && end.is_none() => start = Some(offset),
            PATH_BLOCK_END if start.is_some() && end.is_none() => end = Some(offset + line.len()),
            PATH_BLOCK_START | PATH_BLOCK_END => {
                return Err("the profile has ambiguous PATH block markers");
            }
            _ => {}
        }
        offset += line.len();
    }
    match (start, end) {
        (Some(start), Some(end)) => Ok(format!("{}{block}{}", &text[..start], &text[end..])),
        (None, None) => {
            let separator = if text.is_empty() || text.ends_with('\n') {
                "\n"
            } else {
                "\n\n"
            };
            Ok(format!("{text}{separator}{block}"))
        }
        _ => Err("the profile has an incomplete PATH block"),
    }
}

/// Append or upgrade only the managed profile block, keeping the user's other text.
/// `true` when a block stands in the profile afterwards.
fn wire_path(
    p: &Places,
    env: &ShellEnv,
    coming: bool,
    out: &mut dyn Write,
    err: &mut dyn Write,
) -> bool {
    let shell = env.shell_name();
    let Some(rc) = rc_target(p, env) else {
        if hook_of(p, "bash").is_file() {
            let _ = writeln!(
                err,
                "atpkg: NOTE: source ~/.aterm/shell.d/{}.* from your {} profile to get the ALab \
                 toolset on PATH",
                crate::hooks::HOOK_BASENAME,
                if shell.is_empty() { "shell" } else { shell }
            );
        }
        return false;
    };
    let hook = hook_of(p, shell);
    if !hook.is_file() && !coming {
        let _ = writeln!(out, "atpkg: PATH: no edit — no ALab toolset to put on PATH");
        return false;
    }
    let text = match std::fs::read_to_string(&rc) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(e) => {
            let _ = writeln!(err, "atpkg: cannot read {}: {e}", rc.display());
            return false;
        }
    };
    let block = path_block(p, env);
    let updated = match profile_with_path_block(&text, &block) {
        Ok(updated) => updated,
        Err(why) => {
            let _ = writeln!(err, "atpkg: {}: {why}; no edit", rc.display());
            return false;
        }
    };
    if updated == text {
        let _ = writeln!(
            out,
            "atpkg: ALab toolset already on PATH via {}",
            rc.display()
        );
        return true;
    }
    let bin = p.bin_dir.display();
    // Follow an existing profile symlink without replacing the link itself.
    let destination = if rc.is_symlink() {
        match rc.canonicalize() {
            Ok(path) => path,
            Err(e) => {
                let _ = writeln!(err, "atpkg: cannot resolve {}: {e}", rc.display());
                return false;
            }
        }
    } else {
        rc.clone()
    };
    if let Some(parent) = destination.parent() {
        let _ = made_dir(parent);
    }
    let tmp = destination.with_file_name(format!(".aterm-profile.{}", std::process::id()));
    let wrote = (|| {
        let mode = destination
            .metadata()
            .map(|m| m.mode() & 0o777)
            .unwrap_or(0o600);
        let mut file = crate::platform::open_create_new_write(&tmp, mode)?;
        let written = file
            .write_all(updated.as_bytes())
            .and_then(|()| file.set_permissions(std::fs::Permissions::from_mode(mode)));
        drop(file);
        written
            .and_then(|()| std::fs::rename(&tmp, &destination))
            .inspect_err(|_| {
                let _ = std::fs::remove_file(&tmp);
            })
    })();
    if wrote.is_err() {
        let _ = writeln!(
            err,
            "atpkg: NOTE: could not write {} — add this line yourself for the ALab toolset on \
             PATH:\n{block}",
            rc.display()
        );
        return false;
    }
    let rc_s = rc.display();
    let said = if hook.is_file() {
        format!("added the ALab toolset and {bin} to PATH in {rc_s} — open a new shell")
    } else {
        format!(
            "added {bin} to PATH in {rc_s} — open a new shell; the ALab toolset joins it after \
             aterm's first launch"
        )
    };
    let _ = writeln!(out, "atpkg: {said}");
    true
}

/// A man page to install: its section, its file name, its bytes.
type Page = (String, OsString, Cow<'static, [u8]>);

/// `src`'s `*.[1-9]` pages (a checkout's `man/`); one that cannot be read is left out.
fn checkout_pages(src: &Path) -> Vec<Page> {
    sorted_entries(src)
        .into_iter()
        .filter_map(|page| {
            let section = page
                .extension()
                .and_then(|e| e.to_str())
                .filter(|e| matches!(e.as_bytes(), [b'1'..=b'9']))?
                .to_string();
            let name = page.file_name()?.to_os_string();
            if !page.is_file() {
                return None;
            }
            let bytes = std::fs::read(&page).ok()?;
            Some((section, name, Cow::Owned(bytes)))
        })
        .collect()
}

/// The pages this binary carries ([`CARRIED_MAN_PAGES`]).
fn carried_pages() -> Vec<Page> {
    CARRIED_MAN_PAGES
        .iter()
        .map(|&(section, name, page)| (section.to_string(), name.into(), Cow::Borrowed(page)))
        .collect()
}

/// `dir` and its missing ancestors, made as [`create_dir_all_unshared`] makes them: `0755`,
/// never the `0777 & ~umask` of `create_dir_all`. Shell setup is the first to write under
/// `~/.local/share` on a fresh Linux account (man pages, completions, the desktop entry, its
/// icons; `tools/install.sh` runs it before the toolchain lands), and the atpkg prefix lives
/// below it: under umask `002` a `0775` `~/.local/share` is a group-writable component on
/// the installed Trust toolchain's chain, which `targo trust` refuses.
///
/// [`create_dir_all_unshared`]: aterm_types::fs_restricted::create_dir_all_unshared
fn made_dir(dir: &Path) -> std::io::Result<()> {
    aterm_types::fs_restricted::create_dir_all_unshared(dir, 0o755)
}

/// `bytes` as `dir/name`, mode 644, `dir` made first ([`made_dir`]).
fn write_644(dir: &Path, name: &OsStr, bytes: &[u8]) -> std::io::Result<()> {
    let dest = dir.join(name);
    made_dir(dir)
        .and_then(|()| std::fs::write(&dest, bytes))
        .and_then(|()| std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(0o644)))
}

/// Write `pages` (from `from`, as a plan names it) into the man tree's section directories
/// (mode 644), and say when `$MANPATH` is set and omits the tree. Best effort: a page that
/// cannot be written is left out.
fn install_man_pages(
    p: &Places,
    env: &ShellEnv,
    pages: &[Page],
    from: &str,
    dry: bool,
    out: &mut dyn Write,
    err: &mut dyn Write,
) {
    if dry {
        if !pages.is_empty() {
            let _ = writeln!(
                out,
                "atpkg: man pages: would install {} page(s) from {from} -> {}",
                pages.len(),
                p.man_root.display()
            );
        }
        return;
    }
    let mut n = 0usize;
    for (section, name, bytes) in pages {
        let dir = p.man_root.join(format!("man{section}"));
        if write_644(&dir, name, bytes).is_ok() {
            n += 1;
        }
    }
    if n == 0 {
        return;
    }
    let _ = writeln!(
        out,
        "atpkg: installed {n} man page(s) -> {} (e.g. man aterm)",
        p.man_root.display()
    );
    // ~/.local/share/man is a standard man location most setups search; nudge only when
    // MANPATH is set and omits it.
    if let Some(manpath) = env.manpath.as_deref().filter(|m| !m.is_empty())
        && !manpath
            .split(':')
            .any(|entry| Path::new(entry) == p.man_root)
    {
        let _ = writeln!(
            err,
            "atpkg: NOTE: {} is not in $MANPATH — add it to run `man aterm`",
            p.man_root.display()
        );
    }
}

/// The completion files `shell-setup` writes and the sweep removes: `(shell, front door,
/// path)` — the `aterm-ctl` verb sibling's and the `aterm` front door's, per shell.
fn completion_entries(p: &Places) -> [(&'static str, bool, PathBuf); 6] {
    let zsh = p.xdg_data.join("zsh/site-functions");
    let bash = p.xdg_data.join("bash-completion/completions");
    let fish = p.xdg_config.join("fish/completions");
    [
        ("bash", false, bash.join("aterm-ctl")),
        ("zsh", false, zsh.join("_aterm-ctl")),
        ("fish", false, fish.join("aterm-ctl.fish")),
        ("bash", true, bash.join("aterm")),
        ("zsh", true, zsh.join("_aterm")),
        ("fish", true, fish.join("aterm.fish")),
    ]
}

/// The paths of [`completion_entries`].
fn completion_files(p: &Places) -> Vec<PathBuf> {
    completion_entries(p)
        .into_iter()
        .map(|(_, _, f)| f)
        .collect()
}

/// Publish generated, non-secret setup text through a file this call created. An
/// occupied staging name is never opened or cleaned up. The existing destination is
/// replaced only after the complete write, as setup already does.
fn write_setup_file(tmp: &Path, dest: &Path, bytes: &[u8]) -> std::io::Result<()> {
    // Preserve fs::write's creation mode and the caller's umask for these public files.
    let mut file = crate::platform::open_create_new_write(tmp, 0o666)?;
    let written = file.write_all(bytes);
    drop(file);
    written
        .and_then(|()| std::fs::rename(tmp, dest))
        .inspect_err(|_| {
            // This call created tmp: errors before exclusive creation return above.
            let _ = std::fs::remove_file(tmp);
        })
}

/// Generate the completions with `exe` and write each where its shell loads it from. The
/// final line claims ONLY a shell whose file was written AND has a plausible loader: a file
/// nowhere loads is not an install.
fn install_completions(
    p: &Places,
    env: &ShellEnv,
    exe: &Path,
    dry: bool,
    out: &mut dyn Write,
    err: &mut dyn Write,
) {
    let zsh_dir = p.xdg_data.join("zsh/site-functions");
    // Loaders: bash-completion v2 (stock bash loads nothing from the XDG dir), the dir
    // named in ~/.zshrc (expanded or ~-spelled), fish installed.
    let bash_loader = [
        "/opt/homebrew/etc/profile.d/bash_completion.sh",
        "/usr/local/etc/profile.d/bash_completion.sh",
        "/etc/profile.d/bash_completion.sh",
        "/usr/share/bash-completion/bash_completion",
    ]
    .iter()
    .any(|f| Path::new(f).is_file());
    let tilde = zsh_dir
        .strip_prefix(&p.home)
        .map(|rest| format!("~/{}", rest.display()))
        .unwrap_or_default();
    let zsh_loader = std::fs::read_to_string(p.home.join(".zshrc")).is_ok_and(|rc| {
        rc.contains(&zsh_dir.display().to_string()) || (!tilde.is_empty() && rc.contains(&tilde))
    });
    let fish_loader = env.on_path("fish").is_some();
    // The front door's own completions, probed: a binary without the flag gets only the
    // aterm-ctl sibling's.
    let front_door =
        first_line_bounded(exe, &["--completions", "zsh"], CHILD_HANG).contains("#compdef aterm");
    let mut wrote = (false, false, false);
    for (shell, front, dest) in completion_entries(p) {
        if front && !front_door {
            continue;
        }
        if dry {
            let _ = writeln!(out, "atpkg: completions: {shell} -> {}", dest.display());
            continue;
        }
        let Some(dir) = dest.parent() else {
            continue;
        };
        if made_dir(dir).is_err() {
            continue;
        }
        let args: &[&str] = if front {
            &["--completions", shell]
        } else {
            &["ctl", "--completions", shell]
        };
        let mut cmd = aterm_uds::spawnfd::command(exe);
        cmd.args(args);
        let Ok(run) = aterm_uds::deadline::output_until(&mut cmd, Instant::now() + CHILD_HANG)
        else {
            continue;
        };
        if run.stdout.is_empty() {
            continue;
        }
        // A temp then a rename, so a failed write never leaves half a completion file.
        let tmp = dir.join(format!(
            ".{}.tmp.{}",
            dest.file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default(),
            std::process::id()
        ));
        if write_setup_file(&tmp, &dest, &run.stdout).is_err() {
            continue;
        }
        match shell {
            "bash" => wrote.0 = true,
            "zsh" => wrote.1 = true,
            _ => wrote.2 = true,
        }
    }
    if dry {
        return;
    }
    let claimed: Vec<&str> = [
        ("bash", wrote.0 && bash_loader),
        ("zsh", wrote.1 && zsh_loader),
        ("fish", wrote.2 && fish_loader),
    ]
    .iter()
    .filter(|(_, yes)| *yes)
    .map(|(name, _)| *name)
    .collect();
    if !claimed.is_empty() {
        let _ = writeln!(
            out,
            "atpkg: installed shell completions ({}) — restart your shell to load them",
            claimed.join(", ")
        );
    }
    if wrote.1 && !zsh_loader {
        let z = zsh_dir.display();
        let _ = writeln!(
            err,
            "atpkg: NOTE: zsh completions landed in {z}, which ~/.zshrc does not put on \
             $fpath — add:\n  fpath=(\"{z}\" $fpath)\n  autoload -Uz compinit && compinit"
        );
    }
}

/// Whether `path` may ride the desktop entry's `Exec=` line UNQUOTED: absolute, and only
/// `[A-Za-z0-9/._+-]` — no whitespace, quote, `%` or anything else the Exec parser reads.
/// The spec's quoting rules (double-escaped backslashes, field codes) are subtle enough that
/// an escaper would be its own risk, so a path outside the set is refused, never escaped.
fn desktop_exec_path_ok(path: &Path) -> bool {
    path.to_str().is_some_and(|p| {
        p.starts_with('/')
            && p.bytes()
                .all(|b| b.is_ascii_alphanumeric() || b"/._+-".contains(&b))
    })
}

/// Tell launchers a desktop entry came or went now rather than at their next rescan. Best
/// effort: its absence or failure is fine, desktops rescan on their own.
fn refresh_desktop_database(env: &ShellEnv, xdg_data: &Path) {
    if let Some(update) = env.on_path("update-desktop-database") {
        let mut cmd = aterm_uds::spawnfd::command(update);
        cmd.arg(xdg_data.join("applications"));
        let _ = aterm_uds::deadline::output_until(&mut cmd, Instant::now() + CHILD_HANG);
    }
}

/// An icon to install: its hicolor size directory and its PNG.
type Icon = (String, Cow<'static, [u8]>);

/// The `<size>/apps/aterm.png` icons of the hicolor tree `dir` (a checkout's); one that
/// cannot be read is left out.
fn checkout_icons(dir: &Path) -> Vec<Icon> {
    sorted_entries(dir)
        .into_iter()
        .filter_map(|size| {
            let png = size.join("apps/aterm.png");
            let name = size.file_name()?.to_str()?.to_string();
            if !png.is_file() {
                return None;
            }
            let bytes = std::fs::read(&png).ok()?;
            Some((name, Cow::Owned(bytes)))
        })
        .collect()
}

/// The icons this binary carries ([`HICOLOR_ICONS`]); none off Linux, whose desktop entry
/// this is.
fn carried_icons() -> Vec<Icon> {
    #[cfg(target_os = "linux")]
    let carried = HICOLOR_ICONS
        .iter()
        .map(|&(size, png)| (size.to_string(), Cow::Borrowed(png)))
        .collect();
    #[cfg(not(target_os = "linux"))]
    let carried = Vec::new();
    carried
}

/// The Linux desktop identity. GNOME and KDE know an aterm window by the app id / WM_CLASS
/// the GUI sets (`aterm`) and find its icon, launcher row and dock pin through a desktop
/// file of the same basename; without `aterm.desktop` the window shows a generic gear. So:
/// `aterm.desktop` into the XDG applications dir, launching `<bin dir>/aterm --window`,
/// [`DESKTOP_MARKER`] first, and `icons`' `<size>/apps/aterm.png` beside it — without
/// `icons` (a piped install has no checkout), the ones this binary carries. Best effort,
/// never fatal — the binary is in place either way — and every skip names its remedy.
fn install_desktop_entry(
    p: &Places,
    env: &ShellEnv,
    icons: Option<&Path>,
    dry: bool,
    out: &mut dyn Write,
    err: &mut dyn Write,
) {
    let bin = p.bin_dir.join("aterm");
    // The entry launches the INSTALLED command, so a run that never placed one writes none.
    if !std::fs::metadata(&bin).is_ok_and(|m| m.is_file() && m.permissions().mode() & 0o111 != 0) {
        return;
    }
    if !desktop_exec_path_ok(&bin) {
        let _ = writeln!(
            err,
            "atpkg: SKIPPED the desktop entry: {} contains characters an unquoted desktop \
             Exec= line cannot carry safely (set ATERM_BIN_DIR to a plain path)",
            bin.display()
        );
        return;
    }
    let app_dir = p.xdg_data.join("applications");
    let entry = app_dir.join("aterm.desktop");
    let sources = icons.map_or_else(carried_icons, checkout_icons);
    if dry {
        let _ = writeln!(
            out,
            "atpkg: desktop entry: would write {} (+ the aterm icon at {} size(s))",
            entry.display(),
            sources.len()
        );
        return;
    }
    // A pre-existing entry WITHOUT the marker is someone else's file. Replacing it is what an
    // installer does, but never silently: a later uninstall removes the replacement, and
    // their original stays gone.
    if entry.is_file()
        && !std::fs::read_to_string(&entry)
            .is_ok_and(|text| text.lines().any(|l| l == DESKTOP_MARKER))
    {
        let _ = writeln!(
            out,
            "atpkg: NOTE: replacing a pre-existing {} this installer did not write (no backup \
             is kept)",
            entry.display()
        );
    }
    let b = bin.display();
    let body = format!(
        "{DESKTOP_MARKER}\n[Desktop Entry]\nType=Application\nName=aterm\nGenericName=Terminal\n\
         Comment=The batteries-included terminal for AI\nTryExec={b}\nExec={b} --window\n\
         Icon=aterm\nTerminal=false\nCategories=System;TerminalEmulator;\n\
         Keywords=terminal;shell;console;command line;\nStartupNotify=true\n\
         StartupWMClass=aterm\n"
    );
    // A temp then a rename, so a failed write never leaves half an entry.
    let tmp = app_dir.join(format!(".aterm.desktop.tmp.{}", std::process::id()));
    if made_dir(&app_dir)
        .and_then(|()| write_setup_file(&tmp, &entry, body.as_bytes()))
        .is_err()
    {
        let _ = writeln!(
            err,
            "atpkg: SKIPPED the desktop entry: could not write {}",
            entry.display()
        );
        return;
    }
    let mut placed = 0usize;
    for (size, png) in &sources {
        let dir = p.xdg_data.join(format!("icons/hicolor/{size}/apps"));
        if write_644(&dir, OsStr::new("aterm.png"), png).is_ok() {
            placed += 1;
        }
    }
    refresh_desktop_database(env, &p.xdg_data);
    if placed > 0 {
        let _ = writeln!(
            out,
            "atpkg: installed the desktop entry -> {} (+ the aterm icon at {placed} size(s) \
             under {})",
            entry.display(),
            p.xdg_data.join("icons/hicolor").display()
        );
    } else {
        let _ = writeln!(
            out,
            "atpkg: installed the desktop entry -> {}",
            entry.display()
        );
        let _ = writeln!(
            err,
            "atpkg: NOTE: no aterm icon was written under {} — the launcher entry works, \
             with a generic icon",
            p.xdg_data.join("icons/hicolor").display()
        );
    }
}

// ---------------------------------------------------------------------------------------
// the verbs
// ---------------------------------------------------------------------------------------

/// The places of this process: `$HOME`, `$XDG_DATA_HOME`, `$XDG_CONFIG_HOME`, and
/// install.sh's defaults; `None` when HOME is unset.
fn process_places() -> Option<Places> {
    let home = aterm_types::dirs::home_dir()?;
    let env_dir = |name: &str| {
        std::env::var_os(name)
            .filter(|v| !v.is_empty())
            .map(PathBuf::from)
    };
    Some(Places::defaults(
        &home,
        env_dir("XDG_DATA_HOME").as_deref(),
        env_dir("XDG_CONFIG_HOME").as_deref(),
    ))
}

/// A location flag's value: `--flag <dir>`, the next word.
fn take_dir(
    flag: &str,
    it: &mut std::slice::Iter<'_, String>,
    verb: &str,
) -> Result<PathBuf, ExitCode> {
    match it.next() {
        Some(v) if !v.is_empty() && !v.starts_with('-') => Ok(PathBuf::from(v)),
        _ => Err(crate::cli::usage_error(
            verb,
            Some(&format!("{flag} needs a directory")),
        )),
    }
}

/// `aterm pkg self-uninstall [--dry-run] [--install-dir <dir>] [--bin-dir <dir>]
/// [--store-dir <dir>] [--man-root <dir>] [--man <dir>]`.
pub fn self_uninstall_verb(rest: &[String]) -> ExitCode {
    const VERB: &str = "self-uninstall";
    let Some(mut places) = process_places() else {
        eprintln!("atpkg {VERB}: HOME is unset — nothing to find what install.sh placed under");
        return ExitCode::from(2);
    };
    let (mut dry, mut man) = (false, None);
    let mut it = rest.iter();
    while let Some(arg) = it.next() {
        let parsed = match arg.as_str() {
            "--dry-run" => {
                dry = true;
                Ok(())
            }
            "--install-dir" => take_dir(arg, &mut it, VERB).map(|d| places.install_dir = Some(d)),
            "--bin-dir" => take_dir(arg, &mut it, VERB).map(|d| places.bin_dir = d),
            "--store-dir" => take_dir(arg, &mut it, VERB).map(|d| places.store_dir = d),
            "--man-root" => take_dir(arg, &mut it, VERB).map(|d| places.man_root = d),
            "--man" => take_dir(arg, &mut it, VERB).map(|d| man = Some(d)),
            other => Err(crate::cli::usage_error(
                VERB,
                Some(&format!("unknown argument {other:?}")),
            )),
        };
        if let Err(code) = parsed {
            return code;
        }
    }
    let ok = self_uninstall(
        &places,
        man.as_deref(),
        dry,
        &mut std::io::stdout(),
        &mut std::io::stderr(),
    );
    if ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

/// `aterm pkg shell-setup [--path] [--completions] [--man <dir> | --own-man]
/// [--desktop [--icons <dir>]] [--toolset-coming] [--dry-run] [--bin-dir <dir>] [--man-root <dir>]` — bare: `--path
/// --completions`. `--desktop` is the Linux desktop's: elsewhere it is said and skipped.
pub fn shell_setup_verb(rest: &[String]) -> ExitCode {
    const VERB: &str = "shell-setup";
    let Some(mut places) = process_places() else {
        eprintln!("atpkg {VERB}: HOME is unset — no profile to wire");
        return ExitCode::from(2);
    };
    let mut setup = Setup::default();
    let mut it = rest.iter();
    while let Some(arg) = it.next() {
        let parsed = match arg.as_str() {
            "--path" => {
                setup.path = true;
                Ok(())
            }
            "--completions" => {
                setup.completions = true;
                Ok(())
            }
            "--toolset-coming" => {
                setup.toolset_coming = true;
                Ok(())
            }
            "--dry-run" => {
                setup.dry_run = true;
                Ok(())
            }
            "--desktop" => {
                setup.desktop = true;
                Ok(())
            }
            "--man" => take_dir(arg, &mut it, VERB).map(|d| setup.man = Some(d)),
            "--own-man" => {
                setup.own_man = true;
                Ok(())
            }
            "--icons" => take_dir(arg, &mut it, VERB).map(|d| setup.icons = Some(d)),
            "--bin-dir" => take_dir(arg, &mut it, VERB).map(|d| places.bin_dir = d),
            "--man-root" => take_dir(arg, &mut it, VERB).map(|d| places.man_root = d),
            other => Err(crate::cli::usage_error(
                VERB,
                Some(&format!("unknown argument {other:?}")),
            )),
        };
        if let Err(code) = parsed {
            return code;
        }
    }
    if !setup.path && !setup.completions && setup.man.is_none() && !setup.own_man && !setup.desktop
    {
        setup.path = true;
        setup.completions = true;
    }
    if setup.desktop && !cfg!(target_os = "linux") {
        println!("atpkg: desktop entry: skipped — an XDG desktop entry is a Linux desktop's");
        setup.desktop = false;
    }
    // Resolved: run as its `atpkg` argv0 alias, the binary is still asked by its own name,
    // `aterm`, for the front door's completions.
    let Some(exe) = std::env::current_exe()
        .ok()
        .and_then(|p| std::fs::canonicalize(p).ok())
    else {
        eprintln!("atpkg {VERB}: this binary's own path cannot be read");
        return ExitCode::from(1);
    };
    let ok = shell_setup(
        &places,
        &ShellEnv::of_process(),
        &exe,
        &setup,
        &mut std::io::stdout(),
        &mut std::io::stderr(),
    );
    if ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

